# [AUTO-CURA] Reset de Placa de Áudio / WaveIn DirectShow (CS2)
Get-PnpDevice -Class Media | Where-Object { $_.FriendlyName -like '*TW6802*' -or $_.FriendlyName -like '*TBS*' } | Restart-PnpDevice -Confirm:$false;
